templates.common/home:
{# Reamur ThreeJS Reference — cena declarativa e composicao allowlistada. #}
{{ header }}
<main class="thr-main">
  <div class="thr-container">
    <header class="thr-page-head">
      <p class="thr-kicker">{{ theme.vars.scene_preset|default('threejs') }}</p>
      <h1 class="thr-title">{{ heading_title|default('Tema ThreeJS de referencia') }}</h1>
      <p class="thr-lead">{{ text_tagline|default('Seis presets, tres slots, dois mecanismos 3D.') }}</p>
    </header>
      {% if theme_scene.enabled|default(false) and theme_scene.slot|default('') == 'hero' %}
        {% include 'partial/theme-scene.twig' %}
      {% endif %}
    {% if 'threejs' in theme.flags|default([]) %}<p class="thr-badge">Cena allowlistada ativa</p>{% endif %}
    {% for section in cms_home_sections|default([]) %}
      {% if section == 'hero' %}{% include 'partial/hero-3d.twig' %}
      {% elseif section == 'about' %}{% include 'partial/about.twig' %}
      {% elseif section == 'skills' %}{% include 'partial/skills.twig' %}
      {% elseif section == 'services' %}{% include 'partial/services.twig' %}
      {% elseif section == 'portfolio' %}{% include 'partial/portfolio.twig' %}
      {% elseif section == 'tools' %}{% include 'partial/tools.twig' %}
      {% elseif section == 'news' %}{% include 'partial/news.twig' %}
      {% endif %}
    {% endfor %}
  </div>
</main>

