templates.partial/services:
{# ThreeJS Reference / services — grade #}
<section class="thr-section thr-section--services">
  <div class="thr-container">
<h2 class="thr-h2">{{ text_services_title|default('Servicos') }}</h2>
    {% if services %}<div class="thr-grid">
      {% for item in services %}<article class="thr-card">
        {% if item.image|default('') %}<img class="thr-card-img" src="{{ item.image }}" alt="{{ item.title|default(item.name|default('')) }}" loading="lazy">{% endif %}
        <h3 class="thr-card-title">{{ item.title|default(item.name|default('')) }}</h3>
        <p class="thr-card-text">{{ item.description|default(item.summary|default('')) }}</p>
      </article>{% endfor %}
    </div>{% else %}<p class="thr-empty">Nenhum servico publicado.</p>{% endif %}
  </div>
</section>

